import { cacheLife, cacheTag } from 'next/cache'
import { getAllProducts } from './db.js'

// Cached read of the product catalog. The catalog is read-heavy, so we serve it
// from cache instead of re-querying the database on every request.
//
// `cacheLife('days')` gives a long lifetime: rather than expiring the data on a
// short timer, we keep it cached and rely on on-demand invalidation of the
// `"products"` tag (see the "Sync latest catalog" action) to refresh it when the
// upstream ERP/PIM data actually changes.
export async function getProducts() {
  'use cache'
  cacheLife('days')
  cacheTag('products')

  return getAllProducts()
}

