import { revalidateTag } from 'next/cache'
import { getProducts } from '@/lib/products'

export default async function Page() {
  const products = await getProducts()

  // Inline Server Action for the "Sync latest catalog" trigger.
  //
  // We use `revalidateTag` with the `'max'` profile (stale-while-revalidate)
  // rather than `updateTag`: the admin can keep working immediately while the
  // catalog is briefly stale, and the `"products"` cache is refreshed in the
  // background on the next visit to any view that depends on it. Sync jobs can
  // touch thousands of SKUs, so we favor a responsive admin experience and
  // eventual consistency over blocking the request on freshly recomputed data.
  async function syncCatalog() {
    'use server'

    // Trigger the upstream ERP/PIM sync here. This kicks off the refresh and
    // returns without waiting for every SKU to be recomputed.

    revalidateTag('products', 'max')
  }

  return (
    <div>
      <h1>Product catalog</h1>

      <form action={syncCatalog}>
        <button type="submit">Sync latest catalog</button>
      </form>

      <table>
        <thead>
          <tr>
            <th>ID</th>
            <th>Name</th>
            <th>Price</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id}>
              <td>{product.id}</td>
              <td>{product.name}</td>
              <td>${product.price}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

